2392|static void
2393|InitWalSenderSlot(void)
2394|{
2395|	int			i;
2396|
2397|	/*
2398|	 * WalSndCtl should be set up already (we inherit this by fork() or
2399|	 * EXEC_BACKEND mechanism from the postmaster).
2400|	 */
2401|	Assert(WalSndCtl != NULL);
2402|	Assert(MyWalSnd == NULL);
2403|
2404|	/*
2405|	 * Find a free walsender slot and reserve it. This must not fail due to
2406|	 * the prior check for free WAL senders in InitProcess().
2407|	 */
2408|	for (i = 0; i < max_wal_senders; i++)
2409|	{
2410|		WalSnd	   *walsnd = &WalSndCtl->walsnds[i];
2411|
2412|		SpinLockAcquire(&walsnd->mutex);
2413|
2414|		if (walsnd->pid != 0)
2415|		{
2416|			SpinLockRelease(&walsnd->mutex);
2417|			continue;
2418|		}
2419|		else
2420|		{
2421|			/*
2422|			 * Found a free slot. Reserve it for us.
2423|			 */
2424|			walsnd->pid = MyProcPid;
2425|			walsnd->state = WALSNDSTATE_STARTUP;
2426|			walsnd->sentPtr = InvalidXLogRecPtr;
2427|			walsnd->needreload = false;
2428|			walsnd->write = InvalidXLogRecPtr;
2429|			walsnd->flush = InvalidXLogRecPtr;
2430|			walsnd->apply = InvalidXLogRecPtr;
2431|			walsnd->writeLag = -1;
2432|			walsnd->flushLag = -1;
2433|			walsnd->applyLag = -1;
2434|			walsnd->sync_standby_priority = 0;
2435|			walsnd->latch = &MyProc->procLatch;
2436|			walsnd->replyTime = 0;
2437|			SpinLockRelease(&walsnd->mutex);
2438|			/* don't need the lock anymore */
2439|			MyWalSnd = (WalSnd *) walsnd;
2440|
2441|			break;
2442|		}
2443|	}
2444|
2445|	Assert(MyWalSnd != NULL);
2446|
2447|	/* Arrange to clean up at walsender exit */
2448|	on_shmem_exit(WalSndKill, 0);
2449|}

5088|Size
5089|XLOGShmemSize(void)
5090|{
5091|	Size		size;
5092|
5093|	/*
5094|	 * If the value of wal_buffers is -1, use the preferred auto-tune value.
5095|	 * This isn't an amazingly clean place to do this, but we must wait till
5096|	 * NBuffers has received its final value, and must do it before using the
5097|	 * value of XLOGbuffers to do anything important.
5098|	 */
5099|	if (XLOGbuffers == -1)
5100|	{
5101|		char		buf[32];
5102|
5103|		snprintf(buf, sizeof(buf), "%d", XLOGChooseNumBuffers());
5104|		SetConfigOption("wal_buffers", buf, PGC_POSTMASTER, PGC_S_OVERRIDE);
5105|	}
5106|	Assert(XLOGbuffers > 0);
5107|
5108|	/* XLogCtl */
5109|	size = sizeof(XLogCtlData);
5110|
5111|	/* WAL insertion locks, plus alignment */
5112|	size = add_size(size, mul_size(sizeof(WALInsertLockPadded), NUM_XLOGINSERT_LOCKS + 1));
5113|	/* xlblocks array */
5114|	size = add_size(size, mul_size(sizeof(XLogRecPtr), XLOGbuffers));
5115|	/* extra alignment padding for XLOG I/O buffers */
5116|	size = add_size(size, XLOG_BLCKSZ);
5117|	/* and the buffers themselves */
5118|	size = add_size(size, mul_size(XLOG_BLCKSZ, XLOGbuffers));
5119|
5120|	/*
5121|	 * Note: we don't count ControlFileData, it comes out of the "slop factor"
5122|	 * added by CreateSharedMemoryAndSemaphores.  This lets us use this
5123|	 * routine again below to compute the actual allocation size.
5124|	 */
5125|
5126|	return size;
5127|}

816|Datum
817|fmgr_sql_validator(PG_FUNCTION_ARGS)
818|{
819|	Oid			funcoid = PG_GETARG_OID(0);
820|	HeapTuple	tuple;
821|	Form_pg_proc proc;
822|	List	   *raw_parsetree_list;
823|	List	   *querytree_list;
824|	ListCell   *lc;
825|	bool		isnull;
826|	Datum		tmp;
827|	char	   *prosrc;
828|	parse_error_callback_arg callback_arg;
829|	ErrorContextCallback sqlerrcontext;
830|	bool		haspolyarg;
831|	int			i;
832|
833|	if (!CheckFunctionValidatorAccess(fcinfo->flinfo->fn_oid, funcoid))
834|		PG_RETURN_VOID();
835|
836|	tuple = SearchSysCache1(PROCOID, ObjectIdGetDatum(funcoid));
837|	if (!HeapTupleIsValid(tuple))
838|		elog(ERROR, "cache lookup failed for function %u", funcoid);
839|	proc = (Form_pg_proc) GETSTRUCT(tuple);
840|
841|	/* Disallow pseudotype result */
842|	/* except for RECORD, VOID, or polymorphic */
843|	if (get_typtype(proc->prorettype) == TYPTYPE_PSEUDO &&
844|		proc->prorettype != RECORDOID &&
845|		proc->prorettype != VOIDOID &&
846|		!IsPolymorphicType(proc->prorettype))
847|		ereport(ERROR,
848|				(errcode(ERRCODE_INVALID_FUNCTION_DEFINITION),
849|				 errmsg("SQL functions cannot return type %s",
850|						format_type_be(proc->prorettype))));
851|
852|	/* Disallow pseudotypes in arguments */
853|	/* except for polymorphic */
854|	haspolyarg = false;
855|	for (i = 0; i < proc->pronargs; i++)
856|	{
857|		if (get_typtype(proc->proargtypes.values[i]) == TYPTYPE_PSEUDO)
858|		{
859|			if (IsPolymorphicType(proc->proargtypes.values[i]))
860|				haspolyarg = true;
861|			else
862|				ereport(ERROR,
863|						(errcode(ERRCODE_INVALID_FUNCTION_DEFINITION),
864|						 errmsg("SQL functions cannot have arguments of type %s",
865|								format_type_be(proc->proargtypes.values[i]))));
866|		}
867|	}
868|
869|	/* Postpone body checks if !check_function_bodies */
870|	if (check_function_bodies)
871|	{
872|		tmp = SysCacheGetAttr(PROCOID, tuple, Anum_pg_proc_prosrc, &isnull);
873|		if (isnull)
874|			elog(ERROR, "null prosrc");
875|
876|		prosrc = TextDatumGetCString(tmp);
877|
878|		/*
879|		 * Setup error traceback support for ereport().
880|		 */
881|		callback_arg.proname = NameStr(proc->proname);
882|		callback_arg.prosrc = prosrc;
883|
884|		sqlerrcontext.callback = sql_function_parse_error_callback;
885|		sqlerrcontext.arg = (void *) &callback_arg;
886|		sqlerrcontext.previous = error_context_stack;
887|		error_context_stack = &sqlerrcontext;
888|
889|		/* If we have prosqlbody, pay attention to that not prosrc */
890|		tmp = SysCacheGetAttr(PROCOID, tuple, Anum_pg_proc_prosqlbody, &isnull);
891|		if (!isnull)
892|		{
893|			Node	   *n;
894|
895|			n = stringToNode(TextDatumGetCString(tmp));
896|			if (IsA(n, List))
897|				querytree_list = castNode(List, n);
898|			else
899|				querytree_list = list_make1(list_make1(n));
900|		}
901|		else
902|		{
903|			/*
904|			 * We can't do full prechecking of the function definition if
905|			 * there are any polymorphic input types, because actual datatypes
906|			 * of expression results will be unresolvable.  The check will be
907|			 * done at runtime instead.
908|			 *
909|			 * We can run the text through the raw parser though; this will at
910|			 * least catch silly syntactic errors.
911|			 */
912|			raw_parsetree_list = pg_parse_query(prosrc);
913|			querytree_list = NIL;
914|
915|			if (!haspolyarg)
916|			{
917|				/*
918|				 * OK to do full precheck: analyze and rewrite the queries,
919|				 * then verify the result type.
920|				 */
921|				SQLFunctionParseInfoPtr pinfo;
922|
923|				/* But first, set up parameter information */
924|				pinfo = prepare_sql_fn_parse_info(tuple, NULL, InvalidOid);
925|
926|				foreach(lc, raw_parsetree_list)
927|				{
928|					RawStmt    *parsetree = lfirst_node(RawStmt, lc);
929|					List	   *querytree_sublist;
930|
931|					querytree_sublist = pg_analyze_and_rewrite_params(parsetree,
932|																	  prosrc,
933|																	  (ParserSetupHook) sql_fn_parser_setup,
934|																	  pinfo,
935|																	  NULL);
936|					querytree_list = lappend(querytree_list,
937|											 querytree_sublist);
938|				}
939|			}
940|		}
941|
942|		if (!haspolyarg)
943|		{
944|			Oid			rettype;
945|			TupleDesc	rettupdesc;
946|
947|			check_sql_fn_statements(querytree_list);
948|
949|			(void) get_func_result_type(funcoid, &rettype, &rettupdesc);
950|
951|			(void) check_sql_fn_retval(querytree_list,
952|									   rettype, rettupdesc,
953|									   false, NULL);
954|		}
955|
956|		error_context_stack = sqlerrcontext.previous;
957|	}
958|
959|	ReleaseSysCache(tuple);
960|
961|	PG_RETURN_VOID();
962|}

708|static void
709|execute_sql_string(const char *sql)
710|{
711|	List	   *raw_parsetree_list;
712|	DestReceiver *dest;
713|	ListCell   *lc1;
714|
715|	/*
716|	 * Parse the SQL string into a list of raw parse trees.
717|	 */
718|	raw_parsetree_list = pg_parse_query(sql);
719|
720|	/* All output from SELECTs goes to the bit bucket */
721|	dest = CreateDestReceiver(DestNone);
722|
723|	/*
724|	 * Do parse analysis, rule rewrite, planning, and execution for each raw
725|	 * parsetree.  We must fully execute each query before beginning parse
726|	 * analysis on the next one, since there may be interdependencies.
727|	 */
728|	foreach(lc1, raw_parsetree_list)
729|	{
730|		RawStmt    *parsetree = lfirst_node(RawStmt, lc1);
731|		MemoryContext per_parsetree_context,
732|					oldcontext;
733|		List	   *stmt_list;
734|		ListCell   *lc2;
735|
736|		/*
737|		 * We do the work for each parsetree in a short-lived context, to
738|		 * limit the memory used when there are many commands in the string.
739|		 */
740|		per_parsetree_context =
741|			AllocSetContextCreate(CurrentMemoryContext,
742|								  "execute_sql_string per-statement context",
743|								  ALLOCSET_DEFAULT_SIZES);
744|		oldcontext = MemoryContextSwitchTo(per_parsetree_context);
745|
746|		/* Be sure parser can see any DDL done so far */
747|		CommandCounterIncrement();
748|
749|		stmt_list = pg_analyze_and_rewrite(parsetree,
750|										   sql,
751|										   NULL,
752|										   0,
753|										   NULL);
754|		stmt_list = pg_plan_queries(stmt_list, sql, CURSOR_OPT_PARALLEL_OK, NULL);
755|
756|		foreach(lc2, stmt_list)
757|		{
758|			PlannedStmt *stmt = lfirst_node(PlannedStmt, lc2);
759|
760|			CommandCounterIncrement();
761|
762|			PushActiveSnapshot(GetTransactionSnapshot());
763|
764|			if (stmt->utilityStmt == NULL)
765|			{
766|				QueryDesc  *qdesc;
767|
768|				qdesc = CreateQueryDesc(stmt,
769|										sql,
770|										GetActiveSnapshot(), NULL,
771|										dest, NULL, NULL, 0);
772|
773|				ExecutorStart(qdesc, 0);
774|				ExecutorRun(qdesc, ForwardScanDirection, 0, true);
775|				ExecutorFinish(qdesc);
776|				ExecutorEnd(qdesc);
777|
778|				FreeQueryDesc(qdesc);
779|			}
780|			else
781|			{
782|				if (IsA(stmt->utilityStmt, TransactionStmt))
783|					ereport(ERROR,
784|							(errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
785|							 errmsg("transaction control statements are not allowed within an extension script")));
786|
787|				ProcessUtility(stmt,
788|							   sql,
789|							   false,
790|							   PROCESS_UTILITY_QUERY,
791|							   NULL,
792|							   NULL,
793|							   dest,
794|							   NULL);
795|			}
796|
797|			PopActiveSnapshot();
798|		}
799|
800|		/* Clean up per-parsetree context. */
801|		MemoryContextSwitchTo(oldcontext);
802|		MemoryContextDelete(per_parsetree_context);
803|	}
804|
805|	/* Be sure to advance the command counter after the last script command */
806|	CommandCounterIncrement();
807|}

1470|void
1471|ImportForeignSchema(ImportForeignSchemaStmt *stmt)
1472|{
1473|	ForeignServer *server;
1474|	ForeignDataWrapper *fdw;
1475|	FdwRoutine *fdw_routine;
1476|	AclResult	aclresult;
1477|	List	   *cmd_list;
1478|	ListCell   *lc;
1479|
1480|	/* Check that the foreign server exists and that we have USAGE on it */
1481|	server = GetForeignServerByName(stmt->server_name, false);
1482|	aclresult = pg_foreign_server_aclcheck(server->serverid, GetUserId(), ACL_USAGE);
1483|	if (aclresult != ACLCHECK_OK)
1484|		aclcheck_error(aclresult, OBJECT_FOREIGN_SERVER, server->servername);
1485|
1486|	/* Check that the schema exists and we have CREATE permissions on it */
1487|	(void) LookupCreationNamespace(stmt->local_schema);
1488|
1489|	/* Get the FDW and check it supports IMPORT */
1490|	fdw = GetForeignDataWrapper(server->fdwid);
1491|	if (!OidIsValid(fdw->fdwhandler))
1492|		ereport(ERROR,
1493|				(errcode(ERRCODE_OBJECT_NOT_IN_PREREQUISITE_STATE),
1494|				 errmsg("foreign-data wrapper \"%s\" has no handler",
1495|						fdw->fdwname)));
1496|	fdw_routine = GetFdwRoutine(fdw->fdwhandler);
1497|	if (fdw_routine->ImportForeignSchema == NULL)
1498|		ereport(ERROR,
1499|				(errcode(ERRCODE_FDW_NO_SCHEMAS),
1500|				 errmsg("foreign-data wrapper \"%s\" does not support IMPORT FOREIGN SCHEMA",
1501|						fdw->fdwname)));
1502|
1503|	/* Call FDW to get a list of commands */
1504|	cmd_list = fdw_routine->ImportForeignSchema(stmt, server->serverid);
1505|
1506|	/* Parse and execute each command */
1507|	foreach(lc, cmd_list)
1508|	{
1509|		char	   *cmd = (char *) lfirst(lc);
1510|		import_error_callback_arg callback_arg;
1511|		ErrorContextCallback sqlerrcontext;
1512|		List	   *raw_parsetree_list;
1513|		ListCell   *lc2;
1514|
1515|		/*
1516|		 * Setup error traceback support for ereport().  This is so that any
1517|		 * error in the generated SQL will be displayed nicely.
1518|		 */
1519|		callback_arg.tablename = NULL;	/* not known yet */
1520|		callback_arg.cmd = cmd;
1521|		sqlerrcontext.callback = import_error_callback;
1522|		sqlerrcontext.arg = (void *) &callback_arg;
1523|		sqlerrcontext.previous = error_context_stack;
1524|		error_context_stack = &sqlerrcontext;
1525|
1526|		/*
1527|		 * Parse the SQL string into a list of raw parse trees.
1528|		 */
1529|		raw_parsetree_list = pg_parse_query(cmd);
1530|
1531|		/*
1532|		 * Process each parse tree (we allow the FDW to put more than one
1533|		 * command per string, though this isn't really advised).
1534|		 */
1535|		foreach(lc2, raw_parsetree_list)
1536|		{
1537|			RawStmt    *rs = lfirst_node(RawStmt, lc2);
1538|			CreateForeignTableStmt *cstmt = (CreateForeignTableStmt *) rs->stmt;
1539|			PlannedStmt *pstmt;
1540|
1541|			/*
1542|			 * Because we only allow CreateForeignTableStmt, we can skip parse
1543|			 * analysis, rewrite, and planning steps here.
1544|			 */
1545|			if (!IsA(cstmt, CreateForeignTableStmt))
1546|				elog(ERROR,
1547|					 "foreign-data wrapper \"%s\" returned incorrect statement type %d",
1548|					 fdw->fdwname, (int) nodeTag(cstmt));
1549|
1550|			/* Ignore commands for tables excluded by filter options */
1551|			if (!IsImportableForeignTable(cstmt->base.relation->relname, stmt))
1552|				continue;
1553|
1554|			/* Enable reporting of current table's name on error */
1555|			callback_arg.tablename = cstmt->base.relation->relname;
1556|
1557|			/* Ensure creation schema is the one given in IMPORT statement */
1558|			cstmt->base.relation->schemaname = pstrdup(stmt->local_schema);
1559|
1560|			/* No planning needed, just make a wrapper PlannedStmt */
1561|			pstmt = makeNode(PlannedStmt);
1562|			pstmt->commandType = CMD_UTILITY;
1563|			pstmt->canSetTag = false;
1564|			pstmt->utilityStmt = (Node *) cstmt;
1565|			pstmt->stmt_location = rs->stmt_location;
1566|			pstmt->stmt_len = rs->stmt_len;
1567|
1568|			/* Execute statement */
1569|			ProcessUtility(pstmt, cmd, false,
1570|						   PROCESS_UTILITY_SUBCOMMAND, NULL, NULL,
1571|						   None_Receiver, NULL);
1572|
1573|			/* Be sure to advance the command counter between subcommands */
1574|			CommandCounterIncrement();
1575|
1576|			callback_arg.tablename = NULL;
1577|		}
1578|
1579|		error_context_stack = sqlerrcontext.previous;
1580|	}
1581|}

583|static void
584|init_sql_fcache(FunctionCallInfo fcinfo, Oid collation, bool lazyEvalOK)
585|{
586|	FmgrInfo   *finfo = fcinfo->flinfo;
587|	Oid			foid = finfo->fn_oid;
588|	MemoryContext fcontext;
589|	MemoryContext oldcontext;
590|	Oid			rettype;
591|	TupleDesc	rettupdesc;
592|	HeapTuple	procedureTuple;
593|	Form_pg_proc procedureStruct;
594|	SQLFunctionCachePtr fcache;
595|	List	   *queryTree_list;
596|	List	   *resulttlist;
597|	ListCell   *lc;
598|	Datum		tmp;
599|	bool		isNull;
600|
601|	/*
602|	 * Create memory context that holds all the SQLFunctionCache data.  It
603|	 * must be a child of whatever context holds the FmgrInfo.
604|	 */
605|	fcontext = AllocSetContextCreate(finfo->fn_mcxt,
606|									 "SQL function",
607|									 ALLOCSET_DEFAULT_SIZES);
608|
609|	oldcontext = MemoryContextSwitchTo(fcontext);
610|
611|	/*
612|	 * Create the struct proper, link it to fcontext and fn_extra.  Once this
613|	 * is done, we'll be able to recover the memory after failure, even if the
614|	 * FmgrInfo is long-lived.
615|	 */
616|	fcache = (SQLFunctionCachePtr) palloc0(sizeof(SQLFunctionCache));
617|	fcache->fcontext = fcontext;
618|	finfo->fn_extra = (void *) fcache;
619|
620|	/*
621|	 * get the procedure tuple corresponding to the given function Oid
622|	 */
623|	procedureTuple = SearchSysCache1(PROCOID, ObjectIdGetDatum(foid));
624|	if (!HeapTupleIsValid(procedureTuple))
625|		elog(ERROR, "cache lookup failed for function %u", foid);
626|	procedureStruct = (Form_pg_proc) GETSTRUCT(procedureTuple);
627|
628|	/*
629|	 * copy function name immediately for use by error reporting callback, and
630|	 * for use as memory context identifier
631|	 */
632|	fcache->fname = pstrdup(NameStr(procedureStruct->proname));
633|	MemoryContextSetIdentifier(fcontext, fcache->fname);
634|
635|	/*
636|	 * Resolve any polymorphism, obtaining the actual result type, and the
637|	 * corresponding tupdesc if it's a rowtype.
638|	 */
639|	(void) get_call_result_type(fcinfo, &rettype, &rettupdesc);
640|
641|	fcache->rettype = rettype;
642|
643|	/* Fetch the typlen and byval info for the result type */
644|	get_typlenbyval(rettype, &fcache->typlen, &fcache->typbyval);
645|
646|	/* Remember whether we're returning setof something */
647|	fcache->returnsSet = procedureStruct->proretset;
648|
649|	/* Remember if function is STABLE/IMMUTABLE */
650|	fcache->readonly_func =
651|		(procedureStruct->provolatile != PROVOLATILE_VOLATILE);
652|
653|	/*
654|	 * We need the actual argument types to pass to the parser.  Also make
655|	 * sure that parameter symbols are considered to have the function's
656|	 * resolved input collation.
657|	 */
658|	fcache->pinfo = prepare_sql_fn_parse_info(procedureTuple,
659|											  finfo->fn_expr,
660|											  collation);
661|
662|	/*
663|	 * And of course we need the function body text.
664|	 */
665|	tmp = SysCacheGetAttr(PROCOID,
666|						  procedureTuple,
667|						  Anum_pg_proc_prosrc,
668|						  &isNull);
669|	if (isNull)
670|		elog(ERROR, "null prosrc for function %u", foid);
671|	fcache->src = TextDatumGetCString(tmp);
672|
673|	/* If we have prosqlbody, pay attention to that not prosrc. */
674|	tmp = SysCacheGetAttr(PROCOID,
675|						  procedureTuple,
676|						  Anum_pg_proc_prosqlbody,
677|						  &isNull);
678|
679|	/*
680|	 * Parse and rewrite the queries in the function text.  Use sublists to
681|	 * keep track of the original query boundaries.
682|	 *
683|	 * Note: since parsing and planning is done in fcontext, we will generate
684|	 * a lot of cruft that lives as long as the fcache does.  This is annoying
685|	 * but we'll not worry about it until the module is rewritten to use
686|	 * plancache.c.
687|	 */
688|	queryTree_list = NIL;
689|	if (!isNull)
690|	{
691|		Node	   *n;
692|		List	   *stored_query_list;
693|
694|		n = stringToNode(TextDatumGetCString(tmp));
695|		if (IsA(n, List))
696|			stored_query_list = linitial_node(List, castNode(List, n));
697|		else
698|			stored_query_list = list_make1(n);
699|
700|		foreach(lc, stored_query_list)
701|		{
702|			Query	   *parsetree = lfirst_node(Query, lc);
703|			List	   *queryTree_sublist;
704|
705|			AcquireRewriteLocks(parsetree, true, false);
706|			queryTree_sublist = pg_rewrite_query(parsetree);
707|			queryTree_list = lappend(queryTree_list, queryTree_sublist);
708|		}
709|	}
710|	else
711|	{
712|		List	   *raw_parsetree_list;
713|
714|		raw_parsetree_list = pg_parse_query(fcache->src);
715|
716|		foreach(lc, raw_parsetree_list)
717|		{
718|			RawStmt    *parsetree = lfirst_node(RawStmt, lc);
719|			List	   *queryTree_sublist;
720|
