5139|	MemoryContextSwitchTo(oldcxt);
5140|	MemoryContextDelete(mycxt);
5141|	error_context_stack = sqlerrcontext.previous;
5142|	ReleaseSysCache(func_tuple);
5143|
5144|	return NULL;
